<script setup lang="ts">
import { computed, ref } from 'vue'
import ConfirmationCard from '@/components/ConfirmationCard.vue'
import type { ContractApprovalDecisionBody, ContractApprovalRequest, ContractDeploymentDraftCreateBody, ContractEvaluationAccepted, ContractEvaluationCreateBody, ContractModelRegistrationCreateBody, ContractRollbackDraftCreateBody } from '@/core/contract-types'
import type { ResourceRef } from '@/core/types'
import { useConfirmationStore } from '@/stores/confirmations'
import { useModelCenterStore } from './store'

const store = useModelCenterStore(); const confirmations = useConfirmationStore(); const projectId = ref(''); const modelId = ref(''); const error = ref<string | null>(null); const busy = ref(false)
const registrationName = ref(''); const registrationTaskType = ref(''); const registrationSource = ref<'external_package' | 'training_result'>('external_package'); const registrationArtifactId = ref(''); const registrationExperimentId = ref(''); const selectedRegistrationId = ref<string | null>(null); const registrationAccepted = ref<{ id: string; status: string; job_id: string; resource_ref: ResourceRef } | null>(null)
const evaluationProtocolId = ref(''); const evaluationProtocolVersion = ref(''); const evaluationAccepted = ref<ContractEvaluationAccepted | null>(null)
const approvalEvaluationId = ref(''); const approvalScopeIds = ref(''); const approvalReason = ref(''); const selectedApprovalId = ref<string | null>(null); const approvalDecisionReason = ref('')
const deploymentScopeId = ref(''); const deploymentStage = ref<'STAGING' | 'PRODUCTION'>('PRODUCTION'); const deploymentTargetModelId = ref(''); const deploymentPointerRevision = ref(0); const selectedDraftId = ref<string | null>(null); const selectedRollbackDeploymentId = ref<string | null>(null); const rollbackTargetModelId = ref(''); const rollbackReason = ref('')
const selectedRegistration = computed(() => selectedRegistrationId.value ? store.registrations.find((item) => item.id === selectedRegistrationId.value) ?? null : null); const selectedDraft = computed(() => selectedDraftId.value ? store.drafts.find((item) => item.id === selectedDraftId.value) ?? null : null); const selectedApproval = computed<ContractApprovalRequest | null>(() => selectedApprovalId.value ? store.approvals.find((item) => item.id === selectedApprovalId.value) ?? null : null)
const registrationRef = computed<ResourceRef | null>(() => selectedRegistration.value ? { id: selectedRegistration.value.id, type: 'model_registration' } : null); const deploymentRef = computed<ResourceRef | null>(() => selectedDraft.value ? { id: selectedDraft.value.id, type: 'deployment_draft' } : null); const selectedRollbackDeployment = computed(() => selectedRollbackDeploymentId.value ? store.deployments.find((item) => item.id === selectedRollbackDeploymentId.value) ?? null : null); const registrationConfirmationReady = computed(() => Boolean(registrationRef.value && confirmations.isFor(registrationRef.value, 'model_registration.register'))); const deploymentConfirmationReady = computed(() => Boolean(deploymentRef.value && confirmations.isFor(deploymentRef.value, 'model_deployment.publish'))); const registrationFormReady = computed(() => Boolean(projectId.value && registrationName.value && registrationTaskType.value && registrationArtifactId.value && (registrationSource.value === 'external_package' || registrationExperimentId.value))); const deploymentFormReady = computed(() => Boolean(projectId.value && deploymentScopeId.value && deploymentTargetModelId.value && deploymentPointerRevision.value >= 0))
function showError(reason: unknown, fallback: string) { error.value = reason instanceof Error ? reason.message : fallback }
function selectRegistration(id: string) { selectedRegistrationId.value = id; void store.getRegistration(id, projectId.value).catch((reason) => showError(reason, '读取登记草稿失败')) }
function selectDraft(id: string) { selectedDraftId.value = id; void store.getDeploymentDraft(id, projectId.value).catch((reason) => showError(reason, '读取部署草稿失败')) }
async function load() { if (!projectId.value) return; error.value = null; busy.value = true; try { await store.load(projectId.value) } catch (reason) { showError(reason, '读取模型中心失败') } finally { busy.value = false } }
async function createRegistration() { if (!registrationFormReady.value) return; error.value = null; busy.value = true; try { const source = registrationSource.value === 'external_package' ? { kind: 'external_package' as const, artifact_id: registrationArtifactId.value } : { kind: 'training_result' as const, artifact_id: registrationArtifactId.value, experiment_id: registrationExperimentId.value }; const body: ContractModelRegistrationCreateBody = { project_id: projectId.value, name: registrationName.value, task_type: registrationTaskType.value, source }; const result = await store.createRegistration(body); selectedRegistrationId.value = result.data.id } catch (reason) { showError(reason, '登记草稿创建失败') } finally { busy.value = false } }
async function validateRegistration() { if (!selectedRegistration.value) return; error.value = null; busy.value = true; try { registrationAccepted.value = (await store.validateRegistration(selectedRegistration.value.id, projectId.value, selectedRegistration.value.etag)).data; await store.getRegistration(selectedRegistration.value.id, projectId.value) } catch (reason) { showError(reason, '登记校验失败') } finally { busy.value = false } }
async function registerCandidate() { if (!selectedRegistration.value || !registrationConfirmationReady.value) return; error.value = null; busy.value = true; try { await store.registerCandidate(selectedRegistration.value.id, projectId.value, confirmations.confirmation!.id); await store.listModels(projectId.value) } catch (reason) { showError(reason, '模型登记提交失败') } finally { busy.value = false } }
async function createEvaluation() { if (!projectId.value || !modelId.value || !evaluationProtocolId.value || !evaluationProtocolVersion.value) return; error.value = null; busy.value = true; try { const body: ContractEvaluationCreateBody = { project_id: projectId.value, model_id: modelId.value, protocol_id: evaluationProtocolId.value, protocol_version: evaluationProtocolVersion.value }; evaluationAccepted.value = (await store.createEvaluation(body)).data } catch (reason) { showError(reason, '评测任务创建失败') } finally { busy.value = false } }
async function createApproval() { const scopeIds = approvalScopeIds.value.split(',').map((item) => item.trim()).filter(Boolean); if (!projectId.value || !modelId.value || !approvalEvaluationId.value || !scopeIds.length || !approvalReason.value) return; error.value = null; busy.value = true; try { const result = await store.createApproval(modelId.value, projectId.value, { evaluation_id: approvalEvaluationId.value, scope_ids: scopeIds, reason: approvalReason.value }); selectedApprovalId.value = result.data.id } catch (reason) { showError(reason, '审批请求创建失败') } finally { busy.value = false } }
async function decideApproval(approve: boolean) { if (!selectedApproval.value || !approvalDecisionReason.value) return; const approval = selectedApproval.value; if (typeof approval.revision !== 'number' || !Number.isInteger(approval.revision) || !approval.etag) { error.value = '审批数据缺少 revision 或 etag；为避免使用过期状态，未提交审批。'; return } error.value = null; busy.value = true; try { const decision: ContractApprovalDecisionBody = { reason: approvalDecisionReason.value, expected_revision: approval.revision }; await store.decideApproval(approval.id, projectId.value, decision, approval.etag, approve) } catch (reason) { showError(reason, approve ? '审批通过失败' : '审批拒绝失败') } finally { busy.value = false } }
async function createDeploymentDraft() { if (!deploymentFormReady.value) return; error.value = null; busy.value = true; try { const body: ContractDeploymentDraftCreateBody = { project_id: projectId.value, scope_id: deploymentScopeId.value, stage: deploymentStage.value, target_model_id: deploymentTargetModelId.value, expected_pointer_revision: deploymentPointerRevision.value, rollback_model_id: null }; const result = await store.createDeploymentDraft(body); selectedDraftId.value = result.data.id } catch (reason) { showError(reason, '部署草稿创建失败') } finally { busy.value = false } }
async function validateDeploymentDraft() { if (!selectedDraft.value) return; const draft = selectedDraft.value; if (!draft.etag) { error.value = '部署草稿缺少 etag；为避免校验过期状态，未提交操作。'; return } error.value = null; busy.value = true; try { await store.validateDeploymentDraft(draft.id, projectId.value, draft.etag); await store.getDeploymentDraft(draft.id, projectId.value) } catch (reason) { showError(reason, '部署草稿校验失败') } finally { busy.value = false } }
async function submitDeployment() { if (!selectedDraft.value || !deploymentConfirmationReady.value) return; error.value = null; busy.value = true; try { await store.submitDeployment(selectedDraft.value.id, projectId.value, confirmations.confirmation!.id); await store.listDeployments(projectId.value) } catch (reason) { showError(reason, '部署提交失败') } finally { busy.value = false } }
async function createRollbackDraft(deployment: (typeof store.deployments)[number]) { const pointerRevision = deployment.pointer_revision ?? deployment.expected_pointer_revision; if (!rollbackTargetModelId.value || !rollbackReason.value || pointerRevision < 0) return; error.value = null; busy.value = true; try { const body: ContractRollbackDraftCreateBody = { target_historical_model_id: rollbackTargetModelId.value, expected_pointer_revision: pointerRevision, reason: rollbackReason.value }; const result = await store.createRollbackDraft(deployment.id, projectId.value, body); selectedDraftId.value = result.data.id } catch (reason) { showError(reason, '回滚草稿创建失败') } finally { busy.value = false } }
</script>

<template>
  <div class="view model-center-view"><header class="page-header"><span class="eyebrow">MODEL CENTER · FROZEN M3/M4 API</span><h1>模型中心</h1><p>模型资产登记与生产治理；每个异步任务保留服务端 Location，发布和回滚必须完成校验、人工确认与审批。</p></header>
    <section class="panel toolbar"><label>项目 ID<input v-model="projectId" placeholder="project_id" /></label><button class="secondary" :disabled="busy || !projectId" @click="load">{{ busy ? '读取中…' : '刷新模型与部署' }}</button><span v-if="store.location" class="muted">最近任务：{{ store.location }}</span></section><p v-if="error || store.error" class="error-text">{{ error || store.error }}</p>
    <section class="panel"><div class="section-head"><div><span class="eyebrow">REGISTRY</span><h2>模型注册表</h2><p class="muted">服务端模型必须带项目范围；页面只展示真实 API 返回的数据。</p></div></div><div v-if="store.state === 'loading'" class="placeholder">正在读取模型与部署状态…</div><div v-else-if="!store.models.length" class="placeholder">尚未读取到模型。</div><div v-else class="model-list"><button v-for="model in store.models" :key="model.id" class="record" :class="{ selected: model.id === modelId }" @click="modelId = model.id"><strong>{{ model.name }} · {{ model.version }}</strong><span>{{ model.task_type }} · {{ model.lifecycle_status }} · {{ model.deployment_status }}</span><small>{{ model.id }} · sha256 {{ model.sha256 }}</small></button></div></section>
    <section class="panel"><div class="section-head"><div><span class="eyebrow">REGISTRATION DRAFT</span><h2>登记模型草稿</h2></div></div><div class="grid two-column"><label>名称<input v-model="registrationName" /></label><label>任务类型<input v-model="registrationTaskType" placeholder="如 sfc_separation" /></label><label>来源<select v-model="registrationSource"><option value="external_package">external_package</option><option value="training_result">training_result</option></select></label><label>模型制品 ID<input v-model="registrationArtifactId" /></label><label v-if="registrationSource === 'training_result'">训练实验 ID<input v-model="registrationExperimentId" /></label></div><button class="primary" :disabled="busy || !registrationFormReady" @click="createRegistration">创建登记草稿</button><div v-if="store.registrations.length" class="event-list compact"><button v-for="registration in store.registrations" :key="registration.id" class="secondary" @click="selectRegistration(registration.id)">{{ registration.id }} · {{ registration.status }} · revision {{ registration.revision }}</button></div></section>
    <section v-if="selectedRegistration" class="panel workflow"><h2>登记 {{ selectedRegistration.id }}</h2><dl class="facts"><div><dt>状态</dt><dd>{{ selectedRegistration.status }}</dd></div><div><dt>ETag</dt><dd>{{ selectedRegistration.etag }}</dd></div><div><dt>revision</dt><dd>{{ selectedRegistration.revision }}</dd></div></dl><button class="secondary" :disabled="busy" @click="validateRegistration">服务端校验（202）</button><p v-if="registrationAccepted" class="muted">校验任务 {{ registrationAccepted.job_id }} · {{ registrationAccepted.status }} · {{ store.location || 'Location 未返回' }}</p><ConfirmationCard v-if="registrationRef" :resource-ref="registrationRef" action="model_registration.register" /><button class="primary" :disabled="busy || selectedRegistration.status !== 'VALID' || !registrationConfirmationReady" @click="registerCandidate">登记为 Candidate（需确认）</button></section>
    <section class="panel"><div class="section-head"><div><span class="eyebrow">EVALUATION</span><h2>创建评测</h2></div></div><div class="grid two-column"><label>模型 ID<input v-model="modelId" /></label><label>协议 ID<input v-model="evaluationProtocolId" /></label><label>协议版本<input v-model="evaluationProtocolVersion" /></label></div><button class="primary" :disabled="busy || !projectId || !modelId || !evaluationProtocolId || !evaluationProtocolVersion" @click="createEvaluation">创建评测任务（202）</button><p v-if="evaluationAccepted" class="muted">评测 {{ evaluationAccepted.id }} · {{ evaluationAccepted.status }} · {{ store.location || 'Location 未返回' }}</p></section>
    <section class="panel"><div class="section-head"><div><span class="eyebrow">HUMAN APPROVAL</span><h2>审批请求</h2></div></div><div class="grid two-column"><label>评测 ID<input v-model="approvalEvaluationId" /></label><label>范围 ID（逗号分隔）<input v-model="approvalScopeIds" /></label><label class="wide-field">请求理由<textarea v-model="approvalReason" rows="2" /></label></div><button class="primary" :disabled="busy || !projectId || !modelId || !approvalEvaluationId || !approvalScopeIds || !approvalReason" @click="createApproval">创建审批请求</button><div v-if="store.approvals.length" class="event-list compact"><button v-for="approval in store.approvals" :key="approval.id" class="secondary" @click="selectedApprovalId = approval.id">{{ approval.id }} · {{ approval.status }} · {{ approval.model_id }}</button></div><div v-if="selectedApproval" class="decision-box"><p class="muted">{{ selectedApproval.status }} · ETag {{ selectedApproval.etag }} · revision {{ selectedApproval.revision }}</p><input v-model="approvalDecisionReason" placeholder="审批决定理由" /><div class="row-actions"><button class="primary" :disabled="busy || !approvalDecisionReason || selectedApproval.status !== 'PENDING'" @click="decideApproval(true)">批准</button><button class="secondary" :disabled="busy || !approvalDecisionReason || selectedApproval.status !== 'PENDING'" @click="decideApproval(false)">拒绝</button></div></div></section>
    <section class="panel"><div class="section-head"><div><span class="eyebrow">DEPLOYMENT DRAFT</span><h2>部署与回滚草稿</h2></div></div><div class="grid two-column"><label>范围 ID<input v-model="deploymentScopeId" /></label><label>目标模型 ID<input v-model="deploymentTargetModelId" /></label><label>目标阶段<select v-model="deploymentStage"><option value="STAGING">STAGING</option><option value="PRODUCTION">PRODUCTION</option></select></label><label>期望指针 revision<input v-model.number="deploymentPointerRevision" type="number" min="0" /></label></div><button class="primary" :disabled="busy || !deploymentFormReady" @click="createDeploymentDraft">创建部署草稿</button><div v-if="store.drafts.length" class="event-list compact"><button v-for="draft in store.drafts" :key="draft.id" class="secondary" @click="selectDraft(draft.id)">{{ draft.id }} · {{ draft.operation }} · {{ draft.status }} · {{ draft.target_model_id }}</button></div></section>
    <section v-if="selectedDraft" class="panel workflow"><h2>{{ selectedDraft.operation === 'ROLLBACK' ? '回滚' : '部署' }}草稿 {{ selectedDraft.id }}</h2><dl class="facts"><div><dt>状态</dt><dd>{{ selectedDraft.status }}</dd></div><div><dt>ETag</dt><dd>{{ selectedDraft.etag }}</dd></div><div><dt>revision</dt><dd>{{ selectedDraft.revision }}</dd></div><div><dt>配置哈希</dt><dd>{{ selectedDraft.config_hash }}</dd></div></dl><button class="secondary" :disabled="busy" @click="validateDeploymentDraft">服务端校验</button><ConfirmationCard v-if="deploymentRef" :resource-ref="deploymentRef" action="model_deployment.publish" /><button class="primary" :disabled="busy || selectedDraft.status !== 'READY' || !deploymentConfirmationReady" @click="submitDeployment">提交{{ selectedDraft.operation === 'ROLLBACK' ? '回滚' : '部署' }}（需确认）</button></section>
    <section class="panel"><div class="section-head"><div><span class="eyebrow">DEPLOYMENT LEDGER</span><h2>部署记录与回滚</h2></div></div><div v-if="!store.deployments.length" class="placeholder">尚未读取部署记录。</div><div v-else class="deployment-list"><article v-for="deployment in store.deployments" :key="deployment.id" class="deployment-card"><div><strong>{{ deployment.id }}</strong><span>{{ deployment.operation }} · {{ deployment.stage }} · {{ deployment.status }}</span><small>{{ deployment.scope_id }} · model {{ deployment.target_model_id }} · pointer {{ deployment.pointer_revision ?? '—' }}</small></div><button class="secondary" :class="{ selected: selectedRollbackDeploymentId === deployment.id }" @click="selectedRollbackDeploymentId = deployment.id">选择此记录回滚</button></article></div><div v-if="selectedRollbackDeployment" class="rollback-form"><p class="muted">回滚来源：{{ selectedRollbackDeployment.id }} · 指针 revision {{ selectedRollbackDeployment.pointer_revision ?? selectedRollbackDeployment.expected_pointer_revision }}</p><input v-model="rollbackTargetModelId" placeholder="历史模型 ID" /><input v-model="rollbackReason" placeholder="回滚理由" /><button class="secondary" :disabled="busy || !rollbackTargetModelId || !rollbackReason" @click="createRollbackDraft(selectedRollbackDeployment)">创建回滚草稿</button></div></section>
  </div>
</template>

<style scoped>
.model-center-view { display: grid; gap: 14px; }
.model-center-view > :not(.page-header) { width: 100%; min-width: 0; margin-inline: 0; }
.toolbar { display: flex; align-items: end; gap: 12px; flex-wrap: wrap; }.toolbar label { min-width: 260px; }.section-head { display: flex; justify-content: space-between; gap: 12px; align-items: start; }.model-list, .deployment-list { display: grid; gap: 8px; margin-top: 14px; }.record, .deployment-card { border: 1px solid #d7e3ea; background: #fff; color: #203b4d; border-radius: 10px; padding: 12px; text-align: left; display: grid; gap: 4px; }.record { cursor: pointer; }.record.selected { border-color: #2f819d; box-shadow: 0 0 0 2px #d8eef3; }.record span, .record small, .deployment-card span, .deployment-card small { color: #60788b; font-size: 12px; }.compact { margin-top: 14px; }.workflow { border-left: 3px solid #2f819d; }.decision-box { display: grid; gap: 8px; margin-top: 14px; padding-top: 14px; border-top: 1px solid #e1eaee; }.deployment-card { grid-template-columns: minmax(0, 1fr) minmax(260px, 1fr); align-items: center; }.rollback-form { display: grid; grid-template-columns: 1fr 1fr auto; gap: 8px; }@media (max-width: 760px) { .deployment-card, .rollback-form { grid-template-columns: 1fr; } }
</style>
